import xml.etree.ElementTree as ET,re
ns='{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
ss=[ ''.join(t.text or '' for t in si.iter(ns+'t')) for si in ET.parse('x/xl/sharedStrings.xml').getroot()]
rows={}
for _,el in ET.iterparse('x/xl/worksheets/sheet2.xml',events=('end',)):
    if el.tag==ns+'row':
        r=int(el.get('r'))
        d={}
        for c in el.findall(ns+'c'):
            col=re.match(r'[A-Z]+',c.get('r')).group()
            v=c.find(ns+'v')
            if v is None: continue
            d[col]= ss[int(v.text)] if c.get('t')=='s' else v.text
        if d: rows[r]=d
        el.clear()
for r in sorted(rows)[:12]:
    print(r,rows[r])
print('max',max(rows))
EOF
